package dev.rehan.passthrough.client; import net.minecraft.world.entity.player.PlayerSkin; import net.minecraft.resources.Identifier; public class SkinTest { public static PlayerSkin replace(PlayerSkin base, Identifier tex) throws Exception { Object[] args = new Object[base.getClass().getRecordComponents().length]; for (int i=0; i<args.length; i++) { args[i] = base.getClass().getRecordComponents()[i].getAccessor().invoke(base); } args[0] = tex; return (PlayerSkin) base.getClass().getConstructors()[0].newInstance(args); } }
